function readingRange(reading, step) {
  const half = step / 2;
  return [reading - half, reading + half];
}

function isUnder(range, limit) {
  return range[1] <= limit;
}

function differenceOfReadings(a, b) {
  return a - b;
}

function isUndecided(range, limit) {
  return range[0] < limit && limit < range[1];
}

function diffRange(withReading, withoutReading, step) {
  const diff = withReading - withoutReading;
  return [diff - step, diff + step];
}

