function verdict(withReading, withoutReading, step, limit) {
  const diff = withReading - withoutReading;
  const low = diff - step;
  const high = diff + step;
  if (high <= limit) return 'within';
  if (low > limit) return 'over';
  return 'unknown';
}

function sumRange(readings, step) {
  let total = 0;
  for (const r of readings) total += r;
  const doubt = (readings.length * step) / 2;
  return [total - doubt, total + doubt];
}
